INSERT INTO reviewed_batch VALUES
(950,1714,$mw$E41399C3C945E3062D0D167A1E2E2DB8B268C64A951A15233EA9D377971E284C$mw$,$mw$cf4a8422b00541bedd87f1364707c4b2$mw$,$mw$$mw$,$mw${"Id":1714,"StageId":4,"CategoryId":91,"Points":10,"TitleAr":"إذا كان f(x,y)=x²+2xy+3y²−4x−8y، فما قيمتها الصغرى على المستوى الحقيقي؟","TitleEn":"For f(x,y)=x²+2xy+3y²−4x−8y, find its global minimum value over all real x and y.","QuestionTextAr":"إذا كان f(x,y)=x²+2xy+3y²−4x−8y، فما قيمتها الصغرى على المستوى الحقيقي؟","QuestionTextEn":"For f(x,y)=x²+2xy+3y²−4x−8y, find its global minimum value over all real x and y.","DetailedSolutionAr":"القانون المستخدم: نقاط السكون تحقق ∇f=0، والمصفوفة الهسيّة الموجبة التعريف تثبت أن نقطة السكون حد أدنى كلي.\n\nخطوات الحل: نحل 2x+2y−4=0 و2x+6y−8=0 فنحصل على x=y=1. الهسيّة [[2,2],[2,6]] محددها 8>0 وعنصرها القطري الأول 2>0، فهي موجبة التعريف. بالتعويض f(1,1)=1+2+3−4−8=−6.","DetailedSolutionEn":"Rule used: Solve ∇f=0; a positive-definite Hessian proves a unique global minimum for a quadratic.\n\nSolution steps: Solve 2x+2y−4=0 and 2x+6y−8=0 to get x=y=1. The Hessian [[2,2],[2,6]] has determinant 8>0 and leading entry 2>0, so it is positive definite. Then f(1,1)=1+2+3−4−8=−6.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6845,"Order":1,"LatexCode":"-8","IsCorrect":false},{"Id":6846,"Order":2,"LatexCode":"-6","IsCorrect":true},{"Id":6847,"Order":3,"LatexCode":"-4","IsCorrect":false},{"Id":6848,"Order":4,"LatexCode":"6","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب المشتقتين الجزئيتين وساوِهما بالصفر.","En":"Compute both partial derivatives and set them to zero."},{"Ar":"حل النظام الخطي، وتحقق أن مصفوفة هيس موجبة التعيين قبل حساب قيمة الدالة عند الحل.","En":"Solve the linear system, check that the Hessian is positive definite, and evaluate the function there."}],"Title":{"Ar":"إذا كان f(x,y)=x²+2xy+3y²−4x−8y، فما قيمتها الصغرى على المستوى الحقيقي؟","En":"For f(x,y)=x²+2xy+3y²−4x−8y, find its global minimum value over all real x and y."},"Points":10,"Options":[{"Reason":{"Ar":"−8 أقل من الحد الأدنى المثبت −6.","En":"−8 is below the proven lower bound −6."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"-8"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"-6"},{"Reason":{"Ar":"−4 أكبر من قيمة الدالة عند (1,1).","En":"−4 exceeds the value at (1,1)."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"-4"},{"Reason":{"Ar":"6 يعكس إشارة القيمة الصغرى.","En":"6 reverses the sign of the minimum."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"6"}],"StageId":4,"Question":{"Ar":"إذا كان f(x,y)=x²+2xy+3y²−4x−8y، فما قيمتها الصغرى على المستوى الحقيقي؟","En":"For f(x,y)=x²+2xy+3y²−4x−8y, find its global minimum value over all real x and y."},"Solution":{"Idea":{"Ar":"نكمل مربعين موجبين لتحديد حد أدنى عالمي دون افتراضه.","En":"Complete two positive squares to establish the global minimum."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"$f_x=2x+2y-4=0,\\quad f_y=2x+6y-8=0$","En":"$f_x=2x+2y-4=0,\\quad f_y=2x+6y-8=0$"},{"Ar":"$x+y=2,\\quad x+3y=4\\Rightarrow y=1,\\ x=1$","En":"$x+y=2,\\quad x+3y=4\\Rightarrow y=1,\\ x=1$"},{"Ar":"مصفوفة هيس ثابتة وموجبة التعيين لأن العنصر الأول 2 ومحددها 8 موجبان؛ كما أن إكمال المربع يثبت الحد الأدنى عالمياً.","En":"The constant Hessian is positive definite since its first leading entry 2 and determinant 8 are positive; completing squares also proves the global bound."},{"Ar":"$f=(x+y-2)^2+2(y-1)^2-6\\ge-6$","En":"$f=(x+y-2)^2+2(y-1)^2-6\\ge-6$"}],"Result":{"Ar":"$-6$","En":"$-6$"},"CommonError":{"Ar":"تحقق من أن النقطة حد أدنى عالمي، لا مجرد نقطة ساكنة.","En":"Verify a global minimum, not just a stationary point."},"FormulaLatex":"f=(x+y-2)^2+2(y-1)^2-6","Substitution":{"Ar":"$f(1,1)=-6$","En":"$f(1,1)=-6$"},"Verification":{"Ar":"$H=\\begin{pmatrix}2&2\\\\2&6\\end{pmatrix},\\quad\\det H=8>0$","En":"$H=\\begin{pmatrix}2&2\\\\2&6\\end{pmatrix},\\quad\\det H=8>0$"}},"TrackIds":[19,21],"CategoryId":91,"PrimarySkillId":343,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب المشتقتين الجزئيتين وساوِهما بالصفر.","En":"Compute both partial derivatives and set them to zero."},{"Ar":"حل النظام الخطي، وتحقق أن مصفوفة هيس موجبة التعيين قبل حساب قيمة الدالة عند الحل.","En":"Solve the linear system, check that the Hessian is positive definite, and evaluate the function there."}],"Solution":{"Idea":{"Ar":"نكمل مربعين موجبين لتحديد حد أدنى عالمي دون افتراضه.","En":"Complete two positive squares to establish the global minimum."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"$f_x=2x+2y-4=0,\\quad f_y=2x+6y-8=0$","En":"$f_x=2x+2y-4=0,\\quad f_y=2x+6y-8=0$"},{"Ar":"$x+y=2,\\quad x+3y=4\\Rightarrow y=1,\\ x=1$","En":"$x+y=2,\\quad x+3y=4\\Rightarrow y=1,\\ x=1$"},{"Ar":"مصفوفة هيس ثابتة وموجبة التعيين لأن العنصر الأول 2 ومحددها 8 موجبان؛ كما أن إكمال المربع يثبت الحد الأدنى عالمياً.","En":"The constant Hessian is positive definite since its first leading entry 2 and determinant 8 are positive; completing squares also proves the global bound."},{"Ar":"$f=(x+y-2)^2+2(y-1)^2-6\\ge-6$","En":"$f=(x+y-2)^2+2(y-1)^2-6\\ge-6$"}],"Result":{"Ar":"$-6$","En":"$-6$"},"CommonError":{"Ar":"تحقق من أن النقطة حد أدنى عالمي، لا مجرد نقطة ساكنة.","En":"Verify a global minimum, not just a stationary point."},"FormulaLatex":"f=(x+y-2)^2+2(y-1)^2-6","Substitution":{"Ar":"$f(1,1)=-6$","En":"$f(1,1)=-6$"},"Verification":{"Ar":"$H=\\begin{pmatrix}2&2\\\\2&6\\end{pmatrix},\\quad\\det H=8>0$","En":"$H=\\begin{pmatrix}2&2\\\\2&6\\end{pmatrix},\\quad\\det H=8>0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"−8 أقل من الحد الأدنى المثبت −6.","En":"−8 is below the proven lower bound −6."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"−4 أكبر من قيمة الدالة عند (1,1).","En":"−4 exceeds the value at (1,1)."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"6 يعكس إشارة القيمة الصغرى.","En":"6 reverses the sign of the minimum."},"Order":4}]}$mw$,$mw$نكمل مربعين موجبين لتحديد حد أدنى عالمي دون افتراضه.

$f=(x+y-2)^2+2(y-1)^2-6$

1. $f_x=2x+2y-4=0,\quad f_y=2x+6y-8=0$

2. $x+y=2,\quad x+3y=4\Rightarrow y=1,\ x=1$

3. مصفوفة هيس ثابتة وموجبة التعيين لأن العنصر الأول 2 ومحددها 8 موجبان؛ كما أن إكمال المربع يثبت الحد الأدنى عالمياً.

4. $f=(x+y-2)^2+2(y-1)^2-6\ge-6$

$f(1,1)=-6$

$-6$ بلا وحدة محددة

$H=\begin{pmatrix}2&2\\2&6\end{pmatrix},\quad\det H=8>0$

تحقق من أن النقطة حد أدنى عالمي، لا مجرد نقطة ساكنة.$mw$,$mw$Complete two positive squares to establish the global minimum.

$f=(x+y-2)^2+2(y-1)^2-6$

1. $f_x=2x+2y-4=0,\quad f_y=2x+6y-8=0$

2. $x+y=2,\quad x+3y=4\Rightarrow y=1,\ x=1$

3. The constant Hessian is positive definite since its first leading entry 2 and determinant 8 are positive; completing squares also proves the global bound.

4. $f=(x+y-2)^2+2(y-1)^2-6\ge-6$

$f(1,1)=-6$

$-6$ No specified unit

$H=\begin{pmatrix}2&2\\2&6\end{pmatrix},\quad\det H=8>0$

Verify a global minimum, not just a stationary point.$mw$),
(951,1715,$mw$F3E6FEB05BCB2717F80E332E371292523854A66D2B80DB172476E00EA0D5A517$mw$,$mw$d5087f5219407d8abf4c959620f974be$mw$,$mw$$mw$,$mw${"Id":1715,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"حل المعادلة $3^x=243$ مستخدماً العلاقة العكسية بين الأسس واللوغاريتمات.","TitleEn":"Solve $3^x=243$ using the inverse relationship between exponents and logarithms.","QuestionTextAr":"حل المعادلة $3^x=243$ مستخدماً العلاقة العكسية بين الأسس واللوغاريتمات.","QuestionTextEn":"Solve $3^x=243$ using the inverse relationship between exponents and logarithms.","DetailedSolutionAr":"القانون المستخدم: إذا كان $b^x=y$ مع $b>0$ و$b\\ne1$ فإن $x=\\log_b y$. هنا $x=\\log_3 243$؛ وبما أن $3^5=243$ ينتج $x=5$. التحقق: بالتعويض عن $x=5$ نحصل على $3^5=243$، فتتحقق المعادلة.","DetailedSolutionEn":"Rule used: For b>0 and b≠1, b^x=y is equivalent to x=log_b(y). Thus x=log_3(243). Because 3^5=243, x=5. Substituting the result back gives 3^5=243, confirming the inverse-function solution.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6849,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":6850,"Order":2,"LatexCode":"5","IsCorrect":true},{"Id":6851,"Order":3,"LatexCode":"6","IsCorrect":false},{"Id":6852,"Order":4,"LatexCode":"81","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"عبّر عن 243 كقوة للأساس 3.","En":"Express 243 as a power of 3."},{"Ar":"قارن الأسين بعد توحيد الأساس.","En":"Compare exponents once the bases match."}],"Title":{"Ar":"حل المعادلة $3^x=243$ مستخدماً العلاقة العكسية بين الأسس واللوغاريتمات.","En":"Solve $3^x=243$ using the inverse relationship between exponents and logarithms."},"Points":10,"Options":[{"Reason":{"Ar":"3 مرفوعاً للقوة 4 يساوي 81.","En":"3 to the fourth power is 81."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"5"},{"Reason":{"Ar":"3 مرفوعاً للقوة 6 يساوي 729.","En":"3 to the sixth power is 729."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"6"},{"Reason":{"Ar":"81 ناتج قسمة 243 على 3 وليس الأس.","En":"81 is 243 divided by 3, not the exponent."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"81"}],"StageId":3,"Question":{"Ar":"حل المعادلة $3^x=243$ مستخدماً العلاقة العكسية بين الأسس واللوغاريتمات.","En":"Solve $3^x=243$ using the inverse relationship between exponents and logarithms."},"Solution":{"Idea":{"Ar":"اللوغاريتم عكس رفع الأساس إلى قوة.","En":"Logarithms invert exponentiation."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$243=3\\cdot3\\cdot3\\cdot3\\cdot3=3^5$","En":"$243=3\\cdot3\\cdot3\\cdot3\\cdot3=3^5$"},{"Ar":"الأساس 3 موجب ومختلف عن 1؛ الدالة الأسية أحادية، لذا تتساوى الأسس.","En":"Base 3 is positive and not 1; the exponential function is one-to-one, so exponents are equal."},{"Ar":"$x=\\log_3 243=5$","En":"$x=\\log_3 243=5$"}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"لا تقسم 243 على 3 لإيجاد الأس.","En":"Do not divide 243 by 3 to obtain the exponent."},"FormulaLatex":"b^x=a\\iff x=\\log_b a","Substitution":{"Ar":"$243=3^5\\Rightarrow x=5$","En":"$243=3^5\\Rightarrow x=5$"},"Verification":{"Ar":"$3^5=243$","En":"$3^5=243$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":313,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"عبّر عن 243 كقوة للأساس 3.","En":"Express 243 as a power of 3."},{"Ar":"قارن الأسين بعد توحيد الأساس.","En":"Compare exponents once the bases match."}],"Solution":{"Idea":{"Ar":"اللوغاريتم عكس رفع الأساس إلى قوة.","En":"Logarithms invert exponentiation."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$243=3\\cdot3\\cdot3\\cdot3\\cdot3=3^5$","En":"$243=3\\cdot3\\cdot3\\cdot3\\cdot3=3^5$"},{"Ar":"الأساس 3 موجب ومختلف عن 1؛ الدالة الأسية أحادية، لذا تتساوى الأسس.","En":"Base 3 is positive and not 1; the exponential function is one-to-one, so exponents are equal."},{"Ar":"$x=\\log_3 243=5$","En":"$x=\\log_3 243=5$"}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"لا تقسم 243 على 3 لإيجاد الأس.","En":"Do not divide 243 by 3 to obtain the exponent."},"FormulaLatex":"b^x=a\\iff x=\\log_b a","Substitution":{"Ar":"$243=3^5\\Rightarrow x=5$","En":"$243=3^5\\Rightarrow x=5$"},"Verification":{"Ar":"$3^5=243$","En":"$3^5=243$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"3 مرفوعاً للقوة 4 يساوي 81.","En":"3 to the fourth power is 81."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 مرفوعاً للقوة 6 يساوي 729.","En":"3 to the sixth power is 729."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"81 ناتج قسمة 243 على 3 وليس الأس.","En":"81 is 243 divided by 3, not the exponent."},"Order":4}]}$mw$,$mw$اللوغاريتم عكس رفع الأساس إلى قوة.

$b^x=a\iff x=\log_b a$

1. $243=3\cdot3\cdot3\cdot3\cdot3=3^5$

2. الأساس 3 موجب ومختلف عن 1؛ الدالة الأسية أحادية، لذا تتساوى الأسس.

3. $x=\log_3 243=5$

$243=3^5\Rightarrow x=5$

$5$ بلا وحدة قياس

$3^5=243$

لا تقسم 243 على 3 لإيجاد الأس.$mw$,$mw$Logarithms invert exponentiation.

$b^x=a\iff x=\log_b a$

1. $243=3\cdot3\cdot3\cdot3\cdot3=3^5$

2. Base 3 is positive and not 1; the exponential function is one-to-one, so exponents are equal.

3. $x=\log_3 243=5$

$243=3^5\Rightarrow x=5$

$5$ Dimensionless

$3^5=243$

Do not divide 243 by 3 to obtain the exponent.$mw$),
(952,1716,$mw$18AE23A7A517610C92C0C9483E3B9F48C0E4B4E8E96C515A65E0A0682D2F33C1$mw$,$mw$506166baeac8a0691a9018137dcbb142$mw$,$mw$$mw$,$mw${"Id":1716,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"احسب $\\log_2(8\\times16)$ باستعمال خاصية لوغاريتم حاصل الضرب.","TitleEn":"Evaluate $\\log_2(8\\times16)$ using the logarithm product law.","QuestionTextAr":"احسب $\\log_2(8\\times16)$ باستعمال خاصية لوغاريتم حاصل الضرب.","QuestionTextEn":"Evaluate $\\log_2(8\\times16)$ using the logarithm product law.","DetailedSolutionAr":"القانون المستخدم: $\\log_b(MN)=\\log_b M+\\log_b N$ حيث $M,N>0$. نعوّض $M=8$ و$N=16$: ‏$\\log_2 8=3$ و$\\log_2 16=4$ لأن $2^3=8$ و$2^4=16$. إذن المجموع $3+4=7$، وكذلك $8\\times16=128=2^7$.","DetailedSolutionEn":"Rule used: For positive M,N, log_b(MN)=log_b(M)+log_b(N). With base 2, log_2(8)=3 and log_2(16)=4. Their sum is 3+4=7. Check: 8×16=128=2^7, so the direct logarithm also equals 7.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6853,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":6854,"Order":2,"LatexCode":"7","IsCorrect":true},{"Id":6855,"Order":3,"LatexCode":"5","IsCorrect":false},{"Id":6856,"Order":4,"LatexCode":"11","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اكتب العددين على صورة قوى للعدد 2.","En":"Write both factors as powers of 2."},{"Ar":"طبق خاصية الجداء واجمع اللوغاريتمين.","En":"Apply the product rule and add the logarithms."}],"Title":{"Ar":"احسب $\\log_2(8\\times16)$ باستعمال خاصية لوغاريتم حاصل الضرب.","En":"Evaluate $\\log_2(8\\times16)$ using the logarithm product law."},"Points":10,"Options":[{"Reason":{"Ar":"4 لوغاريتم 16 وحده.","En":"4 is the logarithm of 16 alone."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"7"},{"Reason":{"Ar":"5 لا يساوي مجموع الأسين 3 و4.","En":"5 is not the sum of exponents 3 and 4."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"5"},{"Reason":{"Ar":"11 لا يساوي مجموع الأسين 3 و4.","En":"11 is not the sum of exponents 3 and 4."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"11"}],"StageId":3,"Question":{"Ar":"احسب $\\log_2(8\\times16)$ باستعمال خاصية لوغاريتم حاصل الضرب.","En":"Evaluate $\\log_2(8\\times16)$ using the logarithm product law."},"Solution":{"Idea":{"Ar":"لوغاريتم الجداء يساوي مجموع اللوغاريتمات للأساس نفسه عند إيجابية المدخلات.","En":"The logarithm of a product equals the sum of logarithms with the same base for positive arguments."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المدخلان موجبان والأساس 2 صالح، فتطبق قاعدة الجداء.","En":"Both arguments are positive and base 2 is valid, so use the product rule."},{"Ar":"$8=2^3,\\quad16=2^4$","En":"$8=2^3,\\quad16=2^4$"},{"Ar":"$\\log_2(8\\cdot16)=3+4=7$","En":"$\\log_2(8\\cdot16)=3+4=7$"}],"Result":{"Ar":"$7$","En":"$7$"},"CommonError":{"Ar":"لا تضرب قيم اللوغاريتمين.","En":"Do not multiply the logarithm values."},"FormulaLatex":"\\log_b(uv)=\\log_bu+\\log_bv","Substitution":{"Ar":"$\\log_2 8+\\log_2 16=3+4=7$","En":"$\\log_2 8+\\log_2 16=3+4=7$"},"Verification":{"Ar":"$2^7=8\\times16$","En":"$2^7=8\\times16$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":315,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اكتب العددين على صورة قوى للعدد 2.","En":"Write both factors as powers of 2."},{"Ar":"طبق خاصية الجداء واجمع اللوغاريتمين.","En":"Apply the product rule and add the logarithms."}],"Solution":{"Idea":{"Ar":"لوغاريتم الجداء يساوي مجموع اللوغاريتمات للأساس نفسه عند إيجابية المدخلات.","En":"The logarithm of a product equals the sum of logarithms with the same base for positive arguments."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المدخلان موجبان والأساس 2 صالح، فتطبق قاعدة الجداء.","En":"Both arguments are positive and base 2 is valid, so use the product rule."},{"Ar":"$8=2^3,\\quad16=2^4$","En":"$8=2^3,\\quad16=2^4$"},{"Ar":"$\\log_2(8\\cdot16)=3+4=7$","En":"$\\log_2(8\\cdot16)=3+4=7$"}],"Result":{"Ar":"$7$","En":"$7$"},"CommonError":{"Ar":"لا تضرب قيم اللوغاريتمين.","En":"Do not multiply the logarithm values."},"FormulaLatex":"\\log_b(uv)=\\log_bu+\\log_bv","Substitution":{"Ar":"$\\log_2 8+\\log_2 16=3+4=7$","En":"$\\log_2 8+\\log_2 16=3+4=7$"},"Verification":{"Ar":"$2^7=8\\times16$","En":"$2^7=8\\times16$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"4 لوغاريتم 16 وحده.","En":"4 is the logarithm of 16 alone."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"5 لا يساوي مجموع الأسين 3 و4.","En":"5 is not the sum of exponents 3 and 4."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"11 لا يساوي مجموع الأسين 3 و4.","En":"11 is not the sum of exponents 3 and 4."},"Order":4}]}$mw$,$mw$لوغاريتم الجداء يساوي مجموع اللوغاريتمات للأساس نفسه عند إيجابية المدخلات.

$\log_b(uv)=\log_bu+\log_bv$

1. المدخلان موجبان والأساس 2 صالح، فتطبق قاعدة الجداء.

2. $8=2^3,\quad16=2^4$

3. $\log_2(8\cdot16)=3+4=7$

$\log_2 8+\log_2 16=3+4=7$

$7$ بلا وحدة قياس

$2^7=8\times16$

لا تضرب قيم اللوغاريتمين.$mw$,$mw$The logarithm of a product equals the sum of logarithms with the same base for positive arguments.

$\log_b(uv)=\log_bu+\log_bv$

1. Both arguments are positive and base 2 is valid, so use the product rule.

2. $8=2^3,\quad16=2^4$

3. $\log_2(8\cdot16)=3+4=7$

$\log_2 8+\log_2 16=3+4=7$

$7$ Dimensionless

$2^7=8\times16$

Do not multiply the logarithm values.$mw$),
